if not Nq then
return{why=R8e[2994]}
end
return{seen=true,nums={stat=Nq,loSeen=Oq,hiSeen=Pq,transformTo=Kq},why=string.format(R8e[2995],Nq,tostring(Oq),tostring(Pq))}
end
return{seen=true,buff=Gq,nums={maxSeen=Hq.max,steps= #Hq.vals,transformTo=Kq},why=string.format(R8e[2996],Gq,tostring(Hq.max))}
end
if pp.family==R8e[2763]then
local Uq,Vq,Wq={},{},nil
