if pp.family==R8e[2731]then
return{why=R8e[2999]}
end
return{why=R8e[3000]}
end
function pb.learn(ar)
local br={}
for cr in pairs(ar.ids or{})do
local dr,er=pcall(pb.guess,cr)
for gr,ir in ipairs(dr and type(er)==R8e[2563]and er or{})do
if ir.playable and not ir.hand then
local jr,kr=pcall(pb.evidence,ar,cr,ir)
if jr and type(kr)==R8e[2563]and kr.seen then
local lr=type(P.pasBook[cr])==R8e[2563]and P.pasBook[cr]or{}
local mr=type(lr[ir.pid])==R8e[2563]and lr[ir.pid]or nil
local nr={}
for qr,rr in pairs(ir.nums or{})do
nr[qr]=rr
end
for sr,ur in pairs(kr.nums or{})do
nr[sr]=ur
end
local vr=mr~=nil and mr.family==ir.family and(mr.buff==nil or kr.buff==nil or mr.buff==kr.buff)
lr[ir.pid]={family=ir.family,name=ir.name,nums=nr,buff=kr.buff or(mr and mr.buff),who=kr.who or ir.who,trigger=ir.trigger,keyword=ir.keyword,sure=(vr and(tonumber(mr.runs)or 0)>=1)and R8e[2943]or R8e[3001],runs=(vr and(tonumber(mr.runs)or 0)or 0)+1,at=os.time(),why=kr.why}
P.pasBook[cr]=lr
table.insert(br,{id=cr,g=ir,e=lr[ir.pid]})
elseif jr and type(kr)==R8e[2563]then
table.insert(br,{id=cr,g=ir,miss=kr.why})
else
table.insert(br,{id=cr,g=ir,miss=R8e[3002]..tostring(kr)})
end
end
end
end
pb._model={}
return br
end
function pb.unexplained(wr,xr)
if not(wr and wr.firstPlaced and wr.firstPlaced[xr])then
return nil
end
local yr={}
for zr,Ar in ipairs(wr.learned or{})do
if Ar.id==xr and Ar.e and Ar.e.buff then
yr[Ar.e.buff]=true
end
end
local Br={}
for Cr,Dr in pairs(wr.own)do
if(Dr.by[xr]or 0)>0 and not yr[Cr]then
table.insert(Br,{w=R8e[3003],b=Cr,n=Dr.by[xr],max=Dr.max})
end
end
for Er,Fr in pairs(wr.foeBuffs)do
if Fr.near>0 and Fr.first>=wr.firstPlaced[xr]-1 and not yr[Er]then
table.insert(Br,{w=R8e[3004],b=Er,n=Fr.foes,max=Fr.max})
end
end
table.sort(Br,function(Gr,Hr)
return Gr.n>Hr.n
end)
local Ir={}
for Jr=1,math.min(6,#Br)do
Ir[Jr]=Br[Jr]
end
return#Ir>0 and Ir or nil
end
function pb.finish()
