if Mr and bb.trialId then
P.pasBook[bb.trialId]=type(P.pasBook[bb.trialId])==R8e[2563]and P.pasBook[bb.trialId]or{}
P.pasBook[bb.trialId]._tries=(tonumber(P.pasBook[bb.trialId]._tries)or 0)+1
end
for Nr,Or in ipairs(Lr)do
if Or.e then
F.log(1,R8e[2954],string.format(R8e[3005],V.name(Or.id),Or.g.name,pb.words(pb.withBook(Or.id,Or.g)),pb.SURE_WORDS[Or.e.sure]or tostring(Or.e.sure),tostring(Or.e.why)))
elseif Mr and Or.id==bb.trialId then
F.log(1,R8e[2954],string.format(R8e[3006],V.name(Or.id),Or.g.name,tostring(Or.miss)))
end
end
F.saveSoon()
