function W.icWinP(dU)
local eU=dU.rec or W.rec(dU.key)
local fU=W.icLost(dU.room)
local gU=fU and fU.n or 0
local hU=((tonumber(eU.wins)or 0)+(dU.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(eU.runs)or 0)+2)
local iU=W.sim(dU)
local jU,kU=0,0
if iU and tonumber(iU.p)then
local lU=type(iU.trust)==R8e[2563]and iU.trust or nil
local mU=lU~=nil and not lU.ok
local nU=mU and(tonumber(lU.ratio)or 1)>1
if not mU or(nU and not iU.won)or(mU and not nU and iU.won)then
local oU,pU=pcall(gb.styleP,iU)
jU,kU=(oU and tonumber(pU))or tonumber(iU.p),W.IC.SIM_W
end
end
return(hU*2+jU*kU)/(gU+2+kU)
end
