qeb.sell=oeb.rack_count(leb)+(tonumber(ueb)or 0)
qeb.coins=oeb.rack_value(leb)
local veb=math.max(0,neb-reb)
if peb.upgrade then
local web
for xeb,yeb in ipairs({R8e[3645],R8e[3646]})do
local zeb=tonumber(yeb==R8e[3645]and leb.f or leb.s)or 1
local Aeb=zeb<oeb.max_level(yeb)and oeb.get_level(yeb,zeb+1)or nil
local Beb=Aeb and tonumber(Aeb.cost)or nil
if Beb and Beb<=veb and(not web or Beb<web.cost)then
web={kind=yeb,cost=Beb,to=zeb+1}
end
end
if web then
qeb.upgrade=web
veb=veb-web.cost
end
end
local Ceb=oeb.ore_per_sword()
local Deb=oeb.rack_cap(tonumber(leb.f)or 1)*Ceb-math.floor((tonumber(seb)or 0)+1e-6)
