function kb.relicWorth(akb,bkb)
local ckb=bkb._unique_item_data and bkb._unique_item_data._unique_relic_data
if not ckb then
return 0
end
local dkb=N.Items[bkb.item_id]or{}
local ekb,fkb=V.types(akb.unit_id)
if dkb.main_damage_type and dkb.main_damage_type~=R8e[3290]and dkb.main_damage_type~=fkb then
return 0
end
local gkb,hkb=0,0
for ikb,jkb in pairs(ckb._core_damage_type_buffs or{})do
if ekb[jkb.damage_type]then
gkb=gkb+(tonumber(jkb.mul)or 0)+(tonumber(jkb.add_upg)or 0)*0.01+(tonumber(jkb.pen)or 0)*0.001
hkb=hkb+(tonumber(jkb.crit)or 0)
end
end
gkb=gkb+hkb*0.5
local kkb=V.rows(akb.unit_id)
local lkb=kkb and kkb[kkb.max]
local mkb=(lkb and tonumber(lkb.cd)or 0)*V.mult(akb,R8e[3016])
for nkb,okb in pairs(ckb._unique_relic_effects or{})do
local pkb=type(okb.params)==R8e[2563]and okb.params or{}
if okb.id==R8e[3709]then
local qkb=math.min(1,(tonumber(pkb.extra_damage)or 0)*mkb/math.max(1,tonumber(pkb.time_interval)or 40))
local rkb=V.DRONES and V.DRONES[akb.unit_id]
if rkb and rkb.late and mkb>0 then
local skb=1/mkb
qkb=qkb*skb/(skb+(tonumber(rkb.max)or 0)*(tonumber(rkb.late.dmg)or 0)*(tonumber(rkb.hits)or 1)/math.max(0.1,tonumber(rkb.late.cd)or 4))
end
gkb=gkb+qkb
elseif okb.id==R8e[3710]then
gkb=gkb+(tonumber(pkb.dmg_buff)or 0)*0.25
elseif okb.id==R8e[3711]then
gkb=gkb+(tonumber(pkb.dmg_buff)or 0)*hkb
elseif okb.id==R8e[3712]then
if ekb.magic then
gkb=0
else
gkb=gkb+(tonumber(pkb.dmg_buff)or 0)*0.3
end
elseif okb.id==R8e[3713]then
if ekb.water_damage then
gkb=gkb+0.05
end
elseif okb.id==R8e[2715]then
local tkb=tonumber(pkb.duration_buff)or tonumber(type(okb.static_params)==R8e[2563]and okb.static_params.duration_buff)or 2
local vkb,wkb=pcall(V.attackInfo,lkb and lkb.atk,lkb and lkb.range)
local xkb,ykb=vkb and tonumber(wkb.burn)or 0,vkb and tonumber(wkb.dot)or 0
if xkb<=0 then
local zkb,Akb=pcall(pb.model,akb.unit_id,vkb and wkb or nil,lkb)
if zkb and type(Akb)==R8e[2563]and(tonumber(Akb.burnDot)or 0)>0 then
xkb,ykb=Akb.burnDot,ykb+(tonumber(Akb.dot)or 0)
end
end
gkb=gkb+xkb*math.max(0,tkb-1)/(1+ykb)
end
end
return gkb
end
