local nLb=mLb.unit_id
if not fLb[lLb]and not fLb[nLb]and N.Units[nLb]and not V.isFarm(nLb)and not V.allyBuff(nLb)and os.time()-(tonumber(cLb.tried[nLb])or 0)>ab.LAB.AGAIN and(tonumber(type(cLb.blank)==R8e[2563]and cLb.blank[nLb])or 0)<ab.LAB.BLANKS then
local oLb=ab.unitEvidence(nLb)
if oLb<ab.LAB.MIN_EVIDENCE then
local pLb=dLb.collection:get_unit_by_uuid(lLb)or mLb
local qLb=kb.score(pLb)
if qLb>0 and(not iLb or oLb<jLb or(oLb==jLb and qLb>kLb))then
iLb,jLb,kLb={uuid=lLb,id=nLb,u=pLb},oLb,qLb
end
end
end
end
if not iLb then
return
end
local rLb,sLb
for tLb,uLb in ipairs(eLb)do
if not V.isFarm(uLb.id)and not V.allyBuff(uLb.id)and uLb.uuid~=O.evolveUnit then
local vLb=kb.score(uLb.u)
if not rLb or vLb<sLb then
rLb,sLb=uLb,vLb
end
end
end
if not rLb then
return
end
cLb.tried[iLb.id]=os.time()
local wLb=0
for xLb in pairs(cLb.tried)do
wLb=wLb+1
if wLb>300 then
cLb.tried[xLb]=nil
end
end
local yLb,zLb=gb.levelFor(bLb)
if not yLb then
return
end
