end
local ELb,FLb=pcall(gb.run,ALb,gb.teamFrom(BLb,ALb.map),{hpMul=1.1})
local GLb=ELb and type(FLb)==R8e[2563]and(FLb.won or(ALb.infinite and(tonumber(FLb.wave)or 0)>=0.8*W.infReach(bLb.key)))
if not GLb then
