end
local HLb={}
for ILb,JLb in ipairs(eLb)do
table.insert(HLb,JLb.uuid==rLb.uuid and iLb.uuid or JLb.uuid)
end
if ab.equipTeam(HLb,R8e[4295]..V.name(iLb.id))then
cLb.now={id=iLb.id,out=rLb.id,key=bLb.key,at=os.time(),ev=jLb}
F.log(1,R8e[4293],string.format(R8e[4296],V.name(iLb.id),V.name(rLb.id),bLb.label,jLb))
