function eb.upgradeGain(VQb,WQb,XQb,YQb,ZQb,_Qb)
local aRb,bRb=WQb[XQb],WQb[XQb+1]
local cRb=(aRb.cd>0 and aRb.damage/aRb.cd or 0)
local dRb=(bRb.cd>0 and bRb.damage/bRb.cd or 0)*V.aoeUp(bRb.atk,bRb.range)/math.max(0.3,V.aoeUp(aRb.atk,aRb.range))
local eRb=cRb>0 and VQb*(dRb/cRb-1)or(_Qb or 0)
local fRb=WQb[XQb+2]
if fRb and XQb+1<WQb.max and fRb.cd>0 and bRb.cd>0 and cRb>0 then
local gRb=VQb*((fRb.damage/fRb.cd)/cRb-1)
local hRb=YQb+fRb.cost*ZQb
if gRb/hRb>eRb/YQb then
eRb=eRb+(gRb/hRb*YQb-eRb)*0.5
end
end
local iRb=(bRb.range or 0)>(aRb.range or 0)and(1+((bRb.range-aRb.range)/math.max(1,aRb.range)))or 1
return math.max(0,eRb)*iRb
end
function eb.dpsFor(jRb,kRb)
if kRb<=0 then
return 0
end
local lRb={}
for mRb,nRb in ipairs(jRb)do
if not nRb.farm and not nRb.grif and nRb.gain>0 then
table.insert(lRb,nRb)
end
end
table.sort(lRb,function(oRb,pRb)
return oRb.gain/oRb.cost>pRb.gain/pRb.cost
end)
local qRb,rRb=0,0
for sRb,tRb in ipairs(lRb)do
if kRb<=0 then
break
end
rRb=tRb.gain/tRb.cost
local uRb=math.min(1,kRb/tRb.cost)
qRb=qRb+tRb.gain*uRb
kRb=kRb-tRb.cost*uRb
end
return qRb+math.max(0,kRb)*rRb*0.7
end
function eb.shieldDps(vRb,wRb,xRb,yRb,zRb,ARb,BRb)
if(yRb or 0)<=0 or(vRb or 0)<=0 or(zRb or 0)<=0 then
return vRb or 0
end
wRb,xRb,ARb=math.max(0.3,wRb or 2),math.max(1,xRb or 1),ARb or 1
local CRb=vRb*ARb*wRb/xRb
return zRb*xRb/((yRb/math.max(1,BRb or 1)+math.max(1,zRb/CRb))*wRb)/ARb
end
function eb.shieldGain(DRb,ERb,FRb,GRb,HRb,IRb,JRb,KRb)
local LRb,MRb=V.attackInfo(ERb.atk,ERb.range),V.attackInfo(GRb.atk,GRb.range)
local NRb=eb.shieldDps(DRb,(tonumber(ERb.cd)or 2)*(JRb or 1),LRb.n,HRb,IRb,KRb,LRb.hits)
local ORb=eb.shieldDps(FRb,(tonumber(GRb.cd)or 2)*(JRb or 1),MRb.n,HRb,IRb,KRb,MRb.hits)
local PRb=math.max(0,((tonumber(GRb.range)or 0)-(tonumber(ERb.range)or 0))/math.max(1,tonumber(ERb.range)or 1))
return math.max(0,ORb-NRb)+NRb*PRb
end
function eb.shieldGainAhead(QRb,RRb,SRb,TRb,URb,VRb)
local WRb=0
for XRb,YRb in ipairs(URb or{})do
WRb=WRb+(tonumber(YRb.h)or 0)
end
if WRb<=0 then
return nil
end
local ZRb=0
for _Rb,aSb in ipairs(URb)do
if(aSb.h or 0)>0 then
ZRb=ZRb+aSb.h/WRb*eb.shieldGain(QRb,RRb,SRb,TRb,aSb.s or 0,aSb.h,1,VRb)
end
end
return ZRb
end
function eb.shieldWork(bSb,cSb,dSb,eSb,fSb,gSb,hSb,iSb,jSb)
if(eSb or 0)<=0 then
return 0
end
local kSb=3*eSb*(fSb or 1)/math.max(1,gSb or 20)
if(dSb or 0)>=kSb then
return 0
end
return math.max(1,bSb or 1)*math.max(1,jSb or 1)/math.max(0.3,cSb or 2)*math.min(hSb or 0,iSb or 0)
end
function eb.holdGain(lSb,mSb,nSb,oSb)
if not lSb or(mSb or 0)<=0 then
return 0
end
local pSb,qSb=tonumber(lSb.stun)or 0,tonumber(lSb.slowTime)or 0
if pSb<=0 and qSb<=0 then
return 0
end
local rSb,sSb=pSb>0 and pSb or qSb,pSb>0 and 1 or(tonumber(lSb.slowPct)or 0.3)
local tSb=sSb*rSb/(rSb+(tonumber(lSb.ccCd)or 8))
local uSb=tSb/math.max(0.1,1-tSb)
return mSb*uSb*U.clamp(nSb or 0.5,0,1)*math.min(1,(tonumber(lSb.n)or 1)/2)/(1+(oSb or 0))
end
function eb.bleedGain(vSb,wSb,xSb,ySb)
if(vSb or 0)<=0 then
return 0
end
local zSb=wSb or 0
for ASb,BSb in ipairs(xSb or{})do
zSb=math.max(zSb,(tonumber(BSb.hp)or 0)*0.5)
end
return vSb*zSb*(ySb and 0.5 or 1)
end
function eb.bleedShare(CSb,DSb,ESb,FSb)
if CSb<=0 or not DSb then
return 0
end
if FSb then
return DSb==0 and CSb or CSb/(DSb+1)
end
return ESb<DSb and CSb/(DSb-ESb)or 0
end
function eb.keepsUp(GSb,HSb,ISb,JSb,KSb)
local LSb=GSb.coming
if not(LSb and#LSb>0 and GSb.waveSec)then
return true
end
local MSb=GSb.eff or 1
local NSb=GSb.money-ISb
local OSb=(GSb.teamDps or 0)*(GSb.shieldK or 1)+(JSb or 0)*MSb+eb.dpsFor(HSb,math.max(0,NSb))*MSb
local PSb=(GSb.farmNow or 0)+(KSb or 0)
local QSb=(GSb.roadSec or 130)*U.clamp(GSb.cover or 0.6,0.1,1)
local RSb=GSb.hpAlive or 0
for SSb,TSb in ipairs(LSb)do
RSb=math.max(0,RSb+TSb.hp-OSb*GSb.waveSec)
local USb=OSb*QSb
if RSb>USb then
return false,SSb,USb/math.max(1,RSb)
end
if SSb< #LSb then
OSb=OSb+eb.dpsFor(HSb,(TSb.reward or 0)+PSb)*MSb*(0.85^SSb)
end
end
return true
end
eb.BOX_FROM=0.15
eb.REAL_AGE=40
function eb.realK(VSb,WSb,XSb,YSb)
VSb,WSb=tonumber(VSb),tonumber(WSb)
if not VSb or not WSb or WSb<=0 then
return 1
end
local ZSb=math.max(0.1,math.min(3,VSb/WSb))
local _Sb=math.max(0,math.min(1,(tonumber(XSb)or 0)/eb.REAL_AGE))
local aTb=math.max(0.1,math.min(1,tonumber(YSb)or 1))
return aTb+(ZSb-aTb)*_Sb
end
function eb.killsInTime(bTb,cTb,dTb,eTb)
local fTb=tonumber(bTb.hpAlive)or 0
if fTb<=0 then
return true
end
local gTb=(tonumber(bTb.teamDps)or 0)*(bTb.shieldK or 1)+(tonumber(cTb)or 0)*(bTb.eff or 1)
if gTb<=0 then
return false
end
return fTb/gTb<=(bTb.roadSec or 50)*math.max(0,(eTb or 0.6)-(dTb or 0))
end
function eb.boxFrom(hTb)
local iTb=0
for jTb,kTb in ipairs(hTb)do
iTb=iTb+kTb.w
end
if iTb<=0 then
return nil
end
table.sort(hTb,function(lTb,mTb)
return lTb.p<mTb.p
end)
local nTb=0
for oTb,pTb in ipairs(hTb)do
nTb=nTb+pTb.w
if nTb>=iTb*eb.BOX_FROM then
