if not N.PC.is_valid_raycast_hit(Gad.Instance,Fad)then
return nil
end
local Had=Gad.Position
if bb.blockedSpot(Had)then
return nil
end
local Iad=(tonumber(Fad.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Iad*2,2.5,Iad*2)
bb.probe.CFrame=CFrame.new(Had+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return Had
end
