function bb.layoutAdd(scd,tcd,ucd,vcd,wcd)
scd.runs,scd.wins=(tonumber(scd.runs)or 0)+1,(tonumber(scd.wins)or 0)+(tcd and 1 or 0)
scd.sec,scd.wave=type(scd.sec)==R8e[2563]and scd.sec or{},type(scd.wave)==R8e[2563]and scd.wave or{}
if tcd and tonumber(ucd)then
table.insert(scd.sec,math.floor(ucd+0.5))
end
table.insert(scd.wave,tonumber(vcd)or 0)
if tonumber(wcd)then
scd.kills=type(scd.kills)==R8e[2563]and scd.kills or{}
table.insert(scd.kills,math.floor(tonumber(wcd)))
while#scd.kills>bb.LAYOUT_KEEP do
table.remove(scd.kills,1)
end
end
while#scd.sec>bb.LAYOUT_KEEP do
table.remove(scd.sec,1)
end
while#scd.wave>bb.LAYOUT_KEEP do
table.remove(scd.wave,1)
end
