local Gcd,Hcd=(tonumber(xcd.wins)or 0)/Ccd,(tonumber(ycd.wins)or 0)/Dcd
if not zcd and Hcd>=0.5 then
if Gcd+0.25<Hcd and(Ccd>=2 or(Gcd==0 and Hcd>=0.9 and Dcd>=3))then
return string.format(R8e[5098],tonumber(xcd.wins)or 0,Ccd,Ccd==1 and R8e[1479]or R8e[2407],tonumber(ycd.wins)or 0,Dcd,Bcd)
