end
end
end
end
end
if ldd<=kdd then
kdd,ldd=0.75,0.98
end
local xdd=(idd or mdd)+1
local ydd=({kdd,ldd,(kdd+ldd)/2,kdd-(ldd-kdd)/2})[xdd]
