for Gdd,Hdd in ipairs(odd)do
if(U.flat(Hdd.pos)-Ddd).Magnitude<=zdd then
Fdd=Fdd+1
if math.abs(Hdd.prog-ydd)<=0.05 then
Edd=Edd+1
local Idd=U.flat(Hdd.pos)
for Jdd,Kdd in ipairs(ndd)do
if(Idd-Kdd.p).Magnitude<=Kdd.r then
Edd=Edd-0.5
break
end
end
end
end
end
if Edd>0 then
table.insert(Add,{pos=Cdd,sc=Edd,cov=Fdd})
end
if Bdd%60==0 then
