end
end
table.sort(Add,function(Ldd,Mdd)
return Ldd.sc>Mdd.sc
end)
for Ndd,Odd in ipairs(Add)do
local Pdd=bb.valid(Odd.pos,hdd.data)
if Pdd then
F.log(1,R8e[4932],string.format(R8e[5113],V.name(hdd.id),bb.CONTROL_WORDS[xdd],math.floor(ydd*100+0.5)))
return Pdd,Odd.cov,ydd
