function bb.holdSpot(Qdd)
local Rdd,Sdd=gb.holds(Qdd.id)
local Tdd=false
if not Rdd and bb.info and(tonumber(bb.info.regen)or 0)>0 then
local Udd,Vdd=pcall(V.bleeds,Qdd.id)
if Udd and Vdd then
Rdd,Sdd,Tdd=true,Vdd,true
end
end
if not Rdd then
return nil
end
if V.killFed(Qdd.id)then
return nil
end
local Wdd,Xdd={},0
for Ydd,Zdd in ipairs(bb.mine or{})do
local _dd=Zdd._stats
local aed=_dd.id.Value
if _dd:FindFirstChild(R8e[2833])and not V.isFarm(aed)and not V.allyBuff(aed)and aed~=Qdd.id then
local bed,ced=pcall(bb.liveDps,Zdd,aed)
ced=bed and tonumber(ced)or 0
if ced>0 then
table.insert(Wdd,{p=U.flat(Zdd:GetPivot().Position),r=_dd.range.Value,d=ced})
Xdd=Xdd+ced
end
end
end
if#Wdd==0 or Xdd<=0 then
return nil
end
local ded=bb.hurtSamples()
local eed={}
for ged,hed in ipairs(ded)do
local ied,jed=U.flat(hed.pos),0
for ked,led in ipairs(Wdd)do
if(ied-led.p).Magnitude<=led.r then
jed=jed+led.d
end
end
eed[ged]=jed/Xdd
end
local med=V.range(Qdd.u,math.min(tonumber(Sdd)or 0,3,V.rows(Qdd.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local ned,oed,ped
for qed,sed in ipairs(bb.cands)do
local ted,ued,ved=U.flat(sed),0,0
for wed,xed in ipairs(ded)do
if(U.flat(xed.pos)-ted).Magnitude<=med then
ued=ued+eed[wed]
ved=ved+1
end
end
if ued>0 and(not oed or ued>oed)then
local yed=bb.valid(sed,Qdd.data)
if yed then
ned,oed,ped=yed,ued,ved
end
end
if qed%40==0 then
task.wait()
end
end
if not ned then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[Qdd.id]then
bb.holdSaid[Qdd.id]=true
F.log(1,R8e[4932],string.format(Tdd and R8e[5114]or R8e[5115],V.name(Qdd.id)))
end
return ned,ped or 0
end
function bb.buffAtSpot(zed,Aed,Bed)
local Ced={}
for Ded,Eed in ipairs(type(Bed)==R8e[2563]and Bed or{})do
local Fed=type(Eed.b)==R8e[2563]and type(Eed.b.types)==R8e[2563]and tonumber(Eed.b.types[Aed])or nil
if Fed and(Eed.pos-zed).Magnitude<=Eed.range then
local Ged=Ced[Eed.b.attack]
if not Ged then
Ged={n=0,rate=Fed,b=Eed.b}
Ced[Eed.b.attack]=Ged
end
Ged.n=Ged.n+1
if Eed.cd then
Ged.cd=math.min(Ged.cd or math.huge,Eed.cd)
end
end
end
local Hed=0
for Ied,Jed in pairs(Ced)do
local Ked=math.max(1,tonumber(Jed.b.time)or 30)
local Led=math.max(1,Jed.cd or tonumber(Jed.b.cd)or 60)
local Med=V.stackCap(Ied)
local Ned
if Med then
Ned=math.min(Med,(1+Jed.rate)^math.floor(Jed.n*Ked/Led+0.001)-1)
else
Ned=math.min(Jed.rate,Jed.n*Jed.rate*math.min(1,Ked/Led))
end
Hed=math.max(Hed,Ned)
end
return Hed
end
function bb.blockSpot(Oed,Ped)
if V.isFarm(Oed.id)or V.allyBuff(Oed.id)then
return nil
end
local Qed,Red=V.types(Oed.id)
local Sed={}
for Ted,Ued in ipairs(bb.fieldBuffers())do
if type(Ued.b.types)==R8e[2563]and Ued.b.types[Red]then
table.insert(Sed,Ued)
end
end
if#Sed==0 then
