local Ved=(bb.info and tonumber(bb.info.rangeScale))or 1
local Wed=V.range(Oed.u,V.rows(Oed.id).max)*Ved
local Xed=bb.buffAtSpot(Ped,Red,Sed)
local Yed=bb.cover(Ped,Wed)
local Zed,_ed,afd,bfd=nil,Yed*(1+Xed),Xed,Yed
local cfd=0
local dfd=bb.newRadius(Oed)
for efd,ffd in ipairs(Sed)do
for gfd,hfd in ipairs(bb.ringSpots(ffd.pos,(ffd.hr or bb.HB_R)+dfd+0.1,ffd.range))do
local ifd=bb.valid(hfd,Oed.data)
cfd=cfd+1
if cfd%40==0 then
task.wait()
end
if ifd then
local jfd=bb.buffAtSpot(ifd,Red,Sed)
if jfd>Xed+0.001 then
local kfd=bb.cover(ifd,Wed)
local lfd=kfd*(1+jfd)
if lfd>_ed then
Zed,_ed,afd,bfd=ifd,lfd,jfd,kfd
end
end
end
end
end
if not Zed then
return nil
end
F.log(1,R8e[4932],string.format(R8e[5116],V.name(Oed.id),math.floor(afd*100+0.5),math.floor(Xed*100+0.5),math.floor(bfd/math.max(1,Yed)*100+0.5)))
return Zed
end
