bb.BARR_DENSE=0.75
bb.BARR_TEAM,bb.BARR_WAVE=1,1
bb.BARR_GAP=0.1
function bb.barricadeOrder(Sid,Tid)
local Uid,Vid={},0
for Wid,Xid in ipairs(Sid or{})do
local Yid=Vector3 .new(Xid.pos.X,0,Xid.pos.Z)
local Zid,ajd=0,math.huge
for bjd,cjd in ipairs(Tid or{})do
local djd=(cjd.p-Yid).Magnitude
if djd<=cjd.r then
Zid=Zid+1
end
if djd<ajd then
ajd=djd
end
end
if Zid>Vid then
Vid=Zid
end
table.insert(Uid,{s=Xid,n=Zid,d=ajd})
end
if Vid<1 then
return{}
end
local ejd=Vid>=2
local fjd,gjd={},{}
for hjd,ijd in ipairs(Uid)do
if(ejd and ijd.n>=Vid*bb.BARR_DENSE)or(not ejd and ijd.n>=1)then
local jjd=tostring(ijd.s.lane)
if not fjd[jjd]then
fjd[jjd]={}
table.insert(gjd,jjd)
end
table.insert(fjd[jjd],ijd)
end
end
table.sort(gjd)
local kjd=0
for ljd,mjd in ipairs(gjd)do
local njd=fjd[mjd]
if not ejd then
table.sort(njd,function(ojd,pjd)
return(ojd.s.prog or 0)<(pjd.s.prog or 0)
end)
for qjd=2,#njd do
if(njd[qjd].s.prog or 0)-(njd[qjd-1].s.prog or 0)>bb.BARR_GAP then
for rjd= #njd,qjd,-1 do
table.remove(njd,rjd)
end
break
end
end
table.sort(njd,function(sjd,tjd)
if sjd.d~=tjd.d then
return sjd.d<tjd.d
end
return(sjd.s.prog or 0)>(tjd.s.prog or 0)
end)
else
table.sort(njd,function(ujd,vjd)
if ujd.n~=vjd.n then
return ujd.n>vjd.n
end
return(ujd.s.prog or 0)>(vjd.s.prog or 0)
end)
end
kjd=math.max(kjd,#njd)
end
local wjd={}
for xjd=1,kjd do
for yjd,zjd in ipairs(gjd)do
if fjd[zjd][xjd]then
table.insert(wjd,fjd[zjd][xjd].s.pos)
end
end
end
return wjd
end
function bb.defPick(Ajd,Bjd,Cjd,Djd,Ejd,Fjd,Gjd)
local Hjd={}
if Ajd==R8e[2765]or Ajd==R8e[5125]then
local Ijd={}
local Jjd={}
if Ajd==R8e[5125]then
for Kjd,Ljd in ipairs(Ejd or{})do
local Mjd=U.flat(Ljd.pos)
for Njd,Ojd in ipairs(Cjd)do
if(Ojd.p-Mjd).Magnitude<=Ojd.r then
table.insert(Jjd,Mjd)
break
end
end
end
end
for Pjd,Qjd in ipairs(Djd)do
local Rjd=U.flat(Qjd)
local Sjd,Tjd,Ujd=0,0,false
for Vjd,Wjd in ipairs(Cjd)do
local Xjd=(Wjd.p-Rjd).Magnitude
if Xjd<=Bjd then
Sjd=Sjd+1
Tjd=Tjd+Xjd
end
if Gjd and Xjd<=Gjd then
Ujd=true
end
end
local Yjd=0
for Zjd,_jd in ipairs(Jjd)do
if(_jd-Rjd).Magnitude<=Bjd then
Yjd=Yjd+1
end
end
local akd=Ajd==R8e[2765]and(Sjd*1000-Tjd-(Ujd and 500 or 0))or(Yjd*1000+Fjd(Qjd,Bjd)*10+Sjd)
if Ajd~=R8e[2765]or Sjd>0 then
table.insert(Ijd,{p=Qjd,sc=akd})
end
end
table.sort(Ijd,function(bkd,ckd)
return bkd.sc>ckd.sc
end)
for dkd=1,math.min(1000,#Ijd)do
Hjd[dkd]=Ijd[dkd].p
end
elseif Ajd==R8e[5124]or Ajd==R8e[5123]then
local ekd={}
for fkd,gkd in ipairs(Ejd)do
local hkd=U.flat(gkd.pos)
for ikd,jkd in ipairs(Cjd)do
if(jkd.p-hkd).Magnitude<=jkd.r then
table.insert(ekd,gkd)
break
end
end
end
if Ajd==R8e[5123]then
for kkd,lkd in ipairs(bb.barricadeOrder(ekd,Cjd))do
table.insert(Hjd,lkd)
end
end
table.sort(ekd,function(mkd,nkd)
if Ajd==R8e[5124]then
return(mkd.prog or 0)<(nkd.prog or 0)
end
return(mkd.prog or 0)>(nkd.prog or 0)
end)
for okd=3,math.min(#ekd,120)do
table.insert(Hjd,ekd[okd].pos)
end
if#Hjd==0 and ekd[1]then
Hjd[1]=ekd[1].pos
end
end
return Hjd
end
function bb.tnWayPick(pkd,qkd)
if type(qkd)~=R8e[2563]or#pkd==0 then
return nil
end
local function rkd(skd)
local tkd=qkd[skd.style]
if type(tkd)~=R8e[2563]or(tonumber(tkd.n)or 0)<1 then
return 2,0,0
end
if(tonumber(tkd.far)or 0)<0.5*(tonumber(skd.wave)or 0)then
return 3,tonumber(tkd.best)or 0,tonumber(tkd.far)or 0
end
return 1,tonumber(tkd.best)or 0,tonumber(tkd.far)or 0
end
local ukd,vkd,wkd,xkd
for ykd,zkd in ipairs(pkd)do
local Akd,Bkd,Ckd=rkd(zkd)
if not ukd or Akd<vkd or(Akd==vkd and Akd~=2 and(Bkd>wkd or(Bkd==wkd and Ckd>xkd)))then
ukd,vkd,wkd,xkd=ykd,Akd,Bkd,Ckd
end
end
if vkd==2 and ukd==1 then
return nil
end
local Dkd=vkd==1 and string.format(R8e[5126],xkd)or vkd==2 and R8e[5127]or string.format(R8e[5128],xkd)
return ukd,Dkd
end
bb.DEF_APART=6
