function bb.defTick()
if not O.defenses or bb.finished or not(bb.ld and(bb.ld._swordsmith or bb.ld._own_defenses))then
return
end
bb.defFail=bb.defFail or{}
bb.defUsed=bb.defUsed or{}
local Kld={}
for Lld,Mld in ipairs(bb.mine or{})do
local Nld=Mld:FindFirstChild(R8e[2635])
if Nld and Nld:FindFirstChild(R8e[2958])and Nld:FindFirstChild(R8e[2833])and not V.isFarm(Nld.id.Value)then
table.insert(Kld,{p=U.flat(Mld:GetPivot().Position),r=tonumber(Nld.range.Value)or 0})
end
end
if#Kld==0 then
return
end
local Old=bb.defList()
local Pld
do
local Qld=(bb.info and tonumber(bb.info.rangeScale))or 1
for Rld,Sld in ipairs(V.equipped())do
if V.allyBuff(Sld.id)and not V.isFarm(Sld.id)then
local Tld,Uld=pcall(V.range,Sld.u,0)
if Tld and tonumber(Uld)then
Pld=math.max(Pld or 0,Uld*Qld)
end
end
end
