bb.defWornSaid=true
local Vld,Wld,Xld=pcall(ab.defWorn)
if Vld and Wld>0 then
F.log(1,R8e[3664],string.format(R8e[5129],Wld,Wld==1 and R8e[5130]or R8e[5131],Xld,hb.have(R8e[3650]),O.defRepair and R8e[5132]or R8e[5133]))
end
end
for Yld,Zld in ipairs(Old)do
