if not _ld and(bb.defFail[Zld.slot]or 0)<3 and not(bb.defWait and bb.defWait[Zld.slot]and#Kld<=bb.defWait[Zld.slot])then
local amd=bb.defPick(Zld.kind,Zld.range,Kld,bb.cands or{},bb.samples or{},bb.cover,Pld)
local bmd
for cmd,dmd in ipairs(amd)do
