table.insert(bb.defUsed,U.flat(bmd))
if hmd and imd then
Zld.d.placed=true
pcall(bb.defNote,Zld,bmd,Kld)
local jmd=0
for kmd,lmd in ipairs(Kld)do
if(lmd.p-U.flat(bmd)).Magnitude<=Zld.range then
jmd=jmd+1
end
end
F.log(1,R8e[3664],string.format(R8e[5136],Zld.name,bb.spotKey(bmd),Zld.kind==R8e[2765]and string.format(R8e[5137],jmd,#Kld)or(Zld.kind==R8e[5125]and string.format(R8e[5138],bb.cover(bmd,Zld.range))or(Zld.kind==R8e[5124]and R8e[5139]or R8e[5140]))))
else
bb.defFail[Zld.slot]=(bb.defFail[Zld.slot]or 0)+1
if bb.defFail[Zld.slot]>=3 then
F.log(1,R8e[3664],string.format(R8e[5141],Zld.name,tostring(imd)))
end
end
end
return
end
end
end
function bb.unplacedWhy(mmd,nmd)
