function bb.huntWeakText()
local LKd=type(P.hunt)==R8e[2563]and P.hunt.runs or{}
if#LKd<bb.HUNT_WEAK_RUNS then
return nil
end
local MKd,NKd,OKd=0,0,{}
for PKd=1,bb.HUNT_WEAK_RUNS do
