if type(QKd)~=R8e[2563]or QKd.won then
return nil
end
MKd,NKd=MKd+(tonumber(QKd.pearls)or 0),NKd+(tonumber(QKd.sec)or 0)
table.insert(OKd,tonumber(QKd.wave)or 0)
end
if NKd<=0 then
return nil
end
table.sort(OKd)
local RKd=OKd[math.ceil(#OKd/2)]
local SKd=MKd/NKd*60*(tonumber(O.pearlValue)or 0.35)
local TKd={string.format(R8e[5372],bb.HUNT_WEAK_RUNS,RKd,SKd)}
local UKd
for VKd,WKd in ipairs(W.lastScored or{})do
if WKd.kind~=R8e[2586]and(tonumber(WKd.score)or 0)>0 then
UKd=WKd
break
end
end
if UKd then
table.insert(TKd,string.format(R8e[5373],tostring(UKd.label),UKd.score))
end
local XKd=0
for YKd,ZKd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[ZKd]==false then
XKd=XKd+1
end
end
if W.onlyOn()then
table.insert(TKd,R8e[5374])
elseif XKd>=4 then
table.insert(TKd,string.format(R8e[5375],XKd))
end
table.insert(TKd,R8e[5376])
return table.concat(TKd,R8e[2956]),SKd,RKd
end
