return bLd
end
bb.fhP=bb.fhP or 1
local cLd=tonumber(P.fh.pmin)or 1
local dLd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local eLd,fLd,gLd
for hLd,iLd in pairs(aLd)do
local jLd,kLd=1,0
for lLd,mLd in pairs(type(iLd)==R8e[2563]and iLd.effects or{})do
if type(mLd)==R8e[2563]then
