if kLd>0 and bb.fhP*jLd>=cLd and not dLd then
pLd=pLd+100*kLd
elseif kLd>0 then
pLd=pLd-50+kLd
end
if not fLd or pLd>fLd then
eLd,fLd,gLd=hLd,pLd,jLd
end
end
bb.fhP=bb.fhP*(gLd or 1)
local qLd={}
for rLd,sLd in pairs(aLd)do
