function bb.learn()
local XLd=bb.calRun and bb.calRun.potBy
if type(XLd)~=R8e[2563]then
return
end
pcall(bb.sampleHelpers,true)
local YLd={}
for ZLd,_Ld in pairs(bb.ownDealt or{})do
if not V.isFarm(_Ld.id)then
YLd[_Ld.id]=(YLd[_Ld.id]or 0)+(tonumber(_Ld.v)or 0)
end
end
for aMd,bMd in pairs(bb.helperDealt or{})do
if bMd.owner and V.SUMMONER[bMd.owner]and not V.droneHelper(bMd)then
YLd[bMd.owner]=(YLd[bMd.owner]or 0)+(tonumber(bMd.v)or 0)
end
end
local cMd=type(bb.calRun.potExp)==R8e[2563]and bb.calRun.potExp or{}
local dMd,eMd=0,0
local fMd={}
for gMd,hMd in pairs(XLd)do
if hMd>0 then
dMd,eMd=dMd+(YLd[gMd]or 0),eMd+hMd
local iMd=tonumber(cMd[gMd])or hMd
if iMd>0 then
table.insert(fMd,{id=gMd,r=(YLd[gMd]or 0)/iMd,w=iMd})
end
end
end
if dMd<=0 or eMd<=0 then
return
end
table.sort(fMd,function(jMd,kMd)
return jMd.r<kMd.r
end)
local function lMd(mMd)
local nMd,oMd=0,0
for pMd,qMd in ipairs(fMd)do
if qMd.id~=mMd then
nMd=nMd+qMd.w
end
end
if nMd<=0 then
return nil
end
for rMd,sMd in ipairs(fMd)do
if sMd.id~=mMd then
oMd=oMd+sMd.w
if oMd>=nMd/2 then
return sMd.r
end
end
end
end
bb.lastEff={}
for tMd,uMd in pairs(XLd)do
local vMd=lMd(tMd)
if uMd>0 and uMd/eMd>0.02 and vMd and vMd>0 then
local wMd=P.learn[tMd]or{eff=1,n=0,v=6}
V.learnUp(tMd,wMd)
local xMd=math.max(0.02,0.25*math.sqrt(30/(30+wMd.n)))
local yMd=U.clamp(((YLd[tMd]or 0)/uMd)/vMd,0.2,6)
bb.lastEff[tMd]=math.floor(yMd*1000+0.5)/1000
wMd.eff=wMd.eff+(yMd-wMd.eff)*xMd
wMd.n=wMd.n+1
P.learn[tMd]=wMd
end
end
local zMd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if zMd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==R8e[2563]and P.mapLearn or{}
local AMd=type(P.mapLearn[zMd])==R8e[2563]and P.mapLearn[zMd]or{}
for BMd,CMd in pairs(bb.lastEff)do
local DMd=type(AMd[BMd])==R8e[2563]and AMd[BMd]or{eff=CMd,n=0,v=6}
if(tonumber(DMd.v)or 0)<4 then
DMd.eff,DMd.v=(tonumber(DMd.eff)or CMd)*V.secRescale(BMd),4
end
if(tonumber(DMd.v)or 0)<5 then
DMd.eff,DMd.v=(tonumber(DMd.eff)or CMd)*(V.sumRescale(BMd)or 1),5
end
if(tonumber(DMd.v)or 0)<6 then
DMd.eff,DMd.v=(tonumber(DMd.eff)or CMd)*(1-(V.SUMMONER[BMd]and V.SUMMONER[BMd].droneShare or 0)),6
end
local EMd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(DMd.n)or 0))))
DMd.eff=(tonumber(DMd.n)or 0)==0 and CMd or((tonumber(DMd.eff)or CMd)+(CMd-(tonumber(DMd.eff)or CMd))*EMd)
DMd.n=(tonumber(DMd.n)or 0)+1
AMd[BMd]=DMd
end
AMd._at=os.time()
P.mapLearn[zMd]=AMd
if U.count(P.mapLearn)>80 then
local FMd,GMd
for HMd,IMd in pairs(P.mapLearn)do
if not GMd or(tonumber(IMd._at)or 0)<GMd then
FMd,GMd=HMd,tonumber(IMd._at)or 0
end
end
P.mapLearn[FMd]=nil
end
end
end
